import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"The AsyncUp Handbook","description":"","frontmatter":{},"headers":[],"relativePath":"guide/handbook.md","filePath":"guide/handbook.md"}'),s={name:"guide/handbook.md"};function n(r,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="the-asyncup-handbook" tabindex="-1">The AsyncUp Handbook <a class="header-anchor" href="#the-asyncup-handbook" aria-label="Permalink to &quot;The AsyncUp Handbook&quot;">​</a></h1><p>Everything in one place, organised by who you are — following the <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diátaxis</a> split of <em>learning</em>, <em>doing</em>, and <em>looking things up</em>:</p><ul><li><strong><a href="#part-1--setup-operators">Part 1 — Setup</a></strong>: you run the server.</li><li><strong><a href="#part-2--admin-guide">Part 2 — Admin guide</a></strong>: you run the standups.</li><li><strong><a href="#part-3--user-guide">Part 3 — User guide</a></strong>: you answer them.</li><li><strong><a href="#part-4--reference">Part 4 — Reference</a></strong>: every command, endpoint and setting.</li></ul><h2 id="what-asyncup-is" tabindex="-1">What AsyncUp is <a class="header-anchor" href="#what-asyncup-is" aria-label="Permalink to &quot;What AsyncUp is&quot;">​</a></h2><p>AsyncUp replaces the daily standup meeting with a Google Chat flow: every workday each participant gets a DM card; one tap opens a form (three questions plus an optional mood dropdown); answers post as cards under a per-date thread in the team space; at the deadline a wrap-up posts the count and exactly who&#39;s missing. Around that core: blocker tracking and collaboration, polls, trends and charts, weekly digests, webhooks, and web consoles with Google/SAML sign-in. It is MIT-licensed, self-hosted, one container — <strong>everything documented here is in the free open-source core</strong>.</p><hr><h2 id="part-1-—-setup-operators" tabindex="-1">Part 1 — Setup (operators) <a class="header-anchor" href="#part-1-—-setup-operators" aria-label="Permalink to &quot;Part 1 — Setup (operators)&quot;">​</a></h2><p><em>You install and operate the server. Budget ~20 minutes plus your IdP&#39;s paperwork if you enable sign-in.</em></p><h3 id="_1-1-deploy-the-container" tabindex="-1">1.1 Deploy the container <a class="header-anchor" href="#_1-1-deploy-the-container" aria-label="Permalink to &quot;1.1 Deploy the container&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/asyncup-dev/asyncup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> asyncup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # set DASHBOARD_TOKEN and SECRET_KEY (openssl rand -hex 32)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ghcr.io/asyncup-dev/asyncup, amd64 + arm64</span></span></code></pre></div><p>Embedded SQLite is the default; set <code>DATABASE_URL</code> for your own PostgreSQL. Expose the port over HTTPS (Caddy, a tunnel, Cloud Run — see the <a href="./server-setup.html">server setup guide</a> for four complete paths). All <a href="#env-vars">bootstrap environment variables</a> are in the reference below; everything else is configured in the web app and stored encrypted in the database.</p><h3 id="_1-2-connect-google-chat" tabindex="-1">1.2 Connect Google Chat <a class="header-anchor" href="#_1-2-connect-google-chat" aria-label="Permalink to &quot;1.2 Connect Google Chat&quot;">​</a></h3><p>Follow the <a href="./google-chat-setup.html">Google Chat setup guide</a>: create a GCP project, enable the Chat API, create a service account, and point the Chat app at <code>https://&lt;your-host&gt;/chat/events</code>. Then open <code>https://&lt;your-host&gt;/app</code> and sign in with <code>DASHBOARD_TOKEN</code> — on a fresh install the app opens the <strong>guided setup</strong>: Cloud project, service account, the Chat app configuration with a live check for the first signed event, optional sign-in, then the first standup from a template (progress is saved; re-runnable from <code>/app/setup</code>). Until the audience is set, AsyncUp <strong>refuses to process events</strong> (fail closed) and the app shows an action-needed banner.</p><p>Then make the app installable for your people — the <a href="./distribution.html">distribution guide</a> covers the 5-person allowlist path (minutes) and the private Marketplace admin-install path (~1 hour, whole domain).</p><h3 id="_1-3-optional-integrations-—-what-each-one-buys-you" tabindex="-1">1.3 Optional integrations — what each one buys you <a class="header-anchor" href="#_1-3-optional-integrations-—-what-each-one-buys-you" aria-label="Permalink to &quot;1.3 Optional integrations — what each one buys you&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Integration</th><th>Setting(s)</th><th>What you get</th></tr></thead><tbody><tr><td>Calendar OOO sync</td><td>Workspace → checkbox + domain-wide delegation</td><td>People with an <em>Out of office</em> event are auto-marked away</td></tr><tr><td>Directory API</td><td>Workspace → admin email + <code>admin.directory.user.readonly</code> scope</td><td>Emails resolved for everyone (OOO works before first bot contact); Workspace admin detection for the consoles</td></tr><tr><td>Google sign-in</td><td>Sign in with Google → OAuth web client</td><td>Admin/user web consoles with zero per-user setup</td></tr><tr><td>SAML SSO</td><td>Enterprise SSO → IdP entity/URL/cert</td><td>Sign-in via any IdP (Google, Okta, Entra, OneLogin) — <a href="./enterprise-sso.html">details</a></td></tr><tr><td>SCIM provisioning</td><td>Access tokens → SCIM token</td><td>IdP-driven offboarding: deactivate there → removed from every roster here</td></tr><tr><td>Outbound webhooks</td><td>per standup → Webhook URL</td><td>Signed JSON POSTs on submissions and wrap-ups</td></tr></tbody></table><h3 id="_1-4-production-checklist" tabindex="-1">1.4 Production checklist <a class="header-anchor" href="#_1-4-production-checklist" aria-label="Permalink to &quot;1.4 Production checklist&quot;">​</a></h3><ul><li>[ ] GCP project number set (webhook verification on — AsyncUp fails closed without it)</li><li>[ ] HTTPS in front of everything</li><li>[ ] Tokens generated only for endpoints you use (<code>/tick</code>, <code>/export</code>, <code>/scim/v2</code>)</li><li>[ ] <code>SECRET_KEY</code> backed up <strong>outside</strong> database backups (it encrypts stored secrets and signs sessions/webhooks)</li><li>[ ] Database on persistent storage, backed up</li><li>[ ] Upgrades = deploy the new image; schema migrations run automatically on both SQLite and PostgreSQL</li></ul><hr><h2 id="part-2-—-admin-guide" tabindex="-1">Part 2 — Admin guide <a class="header-anchor" href="#part-2-—-admin-guide" aria-label="Permalink to &quot;Part 2 — Admin guide&quot;">​</a></h2><p><em>You create standups and keep them healthy. Everything here needs standup admin (the <code>setup</code> creator, anyone granted <code>admin @user</code>, or a Workspace admin in the web console).</em></p><h3 id="_2-1-first-standup-—-and-see-it-work-immediately" tabindex="-1">2.1 First standup — and see it work immediately <a class="header-anchor" href="#_2-1-first-standup-—-and-see-it-work-immediately" aria-label="Permalink to &quot;2.1 First standup — and see it work immediately&quot;">​</a></h3><p>In the team space:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@AsyncUp setup Engineering</span></span>
<span class="line"><span>@AsyncUp add @Alice @Bob @Carol</span></span>
<span class="line"><span>@AsyncUp timezone Asia/Kolkata</span></span>
<span class="line"><span>@AsyncUp time 09:30</span></span>
<span class="line"><span>@AsyncUp deadline 11:30</span></span>
<span class="line"><span>@AsyncUp run now          ← opens today&#39;s run and prompts everyone right now</span></span></code></pre></div><p><code>run now</code> is the fastest way to demo the whole loop instead of waiting for tomorrow; the standup&#39;s Overview in the web app has a matching <strong>Run now</strong> button. <code>setup</code> refuses duplicate names; a mis-created standup is retired with <code>archive</code> (history stays). Multiple standups can share a space — prefix commands with <code>#&lt;id&gt;</code> (ids shown by <code>status</code>).</p><h3 id="_2-2-day-to-day-configuration" tabindex="-1">2.2 Day-to-day configuration <a class="header-anchor" href="#_2-2-day-to-day-configuration" aria-label="Permalink to &quot;2.2 Day-to-day configuration&quot;">​</a></h3><p>Chat commands and the standup&#39;s Settings tab edit the same settings — use whichever is at hand. The important semantics:</p><ul><li><strong>Prompt time is participant-local</strong> — each person is prompted at <code>time</code> in <em>their</em> timezone (set by them via DM <code>timezone</code> or their page at <code>/app/me</code>); the <strong>deadline is in the standup&#39;s timezone</strong> and closes the run for everyone.</li><li><strong>Mandatory vs optional</strong> (<code>optional @user</code>) controls who the wrap-up counts as missing. Progress views (&quot;3/5 submitted&quot;) count everyone who isn&#39;t away.</li><li><strong>Roster snapshots</strong>: the day&#39;s roster freezes when the run opens; changes apply from the next run.</li><li><strong><code>add @user</code> warns immediately</strong> when the person can&#39;t be DMed yet (Chat app not installed for them) — nobody fails silently at prompt time.</li><li><strong>Custom questions</strong> (<code>questions set Q1 | Q2 | …</code>, up to 10 × 200 chars): questions containing &quot;blocker&quot; get blocker tracking; &quot;yesterday&quot;/&quot;today&quot; get pre-fill.</li></ul><h3 id="_2-3-working-blockers" tabindex="-1">2.3 Working blockers <a class="header-anchor" href="#_2-3-working-blockers" aria-label="Permalink to &quot;2.3 Working blockers&quot;">​</a></h3><p>Blockers open automatically from blocker answers. Untagged ones auto-resolve on the reporter&#39;s next clean submission. To work one as an item: <code>blocker &lt;id&gt; tag @user</code> sends an interactive DM card (✋ Acknowledge · 📝 Add update · ✅ Resolve); tagged blockers need an explicit resolve, nudge daily until acknowledged, and escalate to the configured contact (<code>escalate @user</code>, threshold <code>escalate days N</code>) once stale. <code>blockers</code> lists everything open with age and tags.</p><h3 id="_2-4-insight-and-outputs" tabindex="-1">2.4 Insight and outputs <a class="header-anchor" href="#_2-4-insight-and-outputs" aria-label="Permalink to &quot;2.4 Insight and outputs&quot;">​</a></h3><ul><li><code>status</code> — configuration + live progress; <code>trends</code> — 4 weeks in chat.</li><li><strong>Dashboard standup page</strong> — 8-week charts (participation, mood, blockers), run history, per-day answers, CSV download.</li><li><code>digest on</code> — weekly digest with week-over-week deltas.</li><li><strong>Webhooks</strong> — per-standup URL receives signed JSON on every submission/edit and wrap-up (<a href="#webhooks-ref">payloads &amp; verification</a>).</li><li><code>poll Question? | Option A | Option B</code> — live-updating vote card; everyone can start one.</li></ul><h3 id="_2-5-the-admin-web-console" tabindex="-1">2.5 The admin web console <a class="header-anchor" href="#_2-5-the-admin-web-console" aria-label="Permalink to &quot;2.5 The admin web console&quot;">​</a></h3><p>Workspace admins sign straight into <code>/app</code> (Google or SAML); operators can use <code>?token=</code> while token sign-in is enabled. Once Google or SAML works you can switch the token off (Settings → Sign-in &amp; consoles → Token sign-in). If you later lose the other method, re-enable it directly in the database and restart:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> settings </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tokenSignIn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The console covers app settings, per-standup config, roster management (mandatory/away/admin/remove for people already known to Chat), Run now, charts, history and CSV. Adding <em>new</em> people happens in Chat (<code>add @user</code>) because it needs a Chat identity.</p><hr><h2 id="part-3-—-user-guide" tabindex="-1">Part 3 — User guide <a class="header-anchor" href="#part-3-—-user-guide" aria-label="Permalink to &quot;Part 3 — User guide&quot;">​</a></h2><p><em>You&#39;re on a standup roster. Total daily effort: about a minute.</em></p><h3 id="_3-1-your-daily-flow" tabindex="-1">3.1 Your daily flow <a class="header-anchor" href="#_3-1-your-daily-flow" aria-label="Permalink to &quot;3.1 Your daily flow&quot;">​</a></h3><p>At the standup&#39;s prompt time (in <strong>your</strong> timezone) AsyncUp DMs you a card:</p><ol><li>Tap <strong>Fill standup</strong> — one modal, all questions, one submit.</li><li>Your answers post as your card in the team thread. &quot;Yesterday&quot; comes pre-filled from your previous &quot;today&quot;.</li><li>Change of plans? Reopen <strong>Fill standup</strong> before the deadline — your posted card updates in place, marked <em>edited</em>. After the deadline a first submission still posts, marked <em>late</em>.</li><li>Not today? Tap <strong>🏖️ Skip today</strong> — you&#39;re listed as away, never as missing.</li></ol><h3 id="_3-2-dm-commands-message-the-bot-directly" tabindex="-1">3.2 DM commands (message the bot directly) <a class="header-anchor" href="#_3-2-dm-commands-message-the-bot-directly" aria-label="Permalink to &quot;3.2 DM commands (message the bot directly)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Effect</th></tr></thead><tbody><tr><td><code>vacation</code> (or <code>ooo</code>)</td><td>Pause prompts across all your standups</td></tr><tr><td><code>back</code></td><td>Resume prompts</td></tr><tr><td><code>timezone Asia/Kolkata</code></td><td>Get prompts at the standup&#39;s time in <em>your</em> zone</td></tr><tr><td><code>timezone</code> / <code>timezone reset</code></td><td>Show / clear your personal timezone</td></tr></tbody></table><h3 id="_3-3-your-own-page-—-app-me" tabindex="-1">3.3 Your own page — <code>/app/me</code> <a class="header-anchor" href="#_3-3-your-own-page-—-app-me" aria-label="Permalink to &quot;3.3 Your own page — \`/app/me\`&quot;">​</a></h3><p>Sign in with Google (or your company&#39;s SSO) at <code>https://&lt;host&gt;/app</code>: your standups and today&#39;s status, your recent submissions, and the same vacation/timezone controls as the DMs. If your account isn&#39;t linked to Chat yet, it links automatically the first time you use the bot (or instantly when the Directory integration is on).</p><h3 id="_3-4-when-you-re-tagged-on-a-blocker" tabindex="-1">3.4 When you&#39;re tagged on a blocker <a class="header-anchor" href="#_3-4-when-you-re-tagged-on-a-blocker" aria-label="Permalink to &quot;3.4 When you&#39;re tagged on a blocker&quot;">​</a></h3><p>You get a card: <strong>✋ Acknowledge</strong> tells the reporter you&#39;re on it (and stops the daily nudges), <strong>📝 Add update</strong> broadcasts to everyone involved, <strong>✅ Resolve</strong> closes it. Anyone can also vote in <code>poll</code> cards — tap an option; tap another to change your vote.</p><hr><h2 id="part-4-—-reference" tabindex="-1">Part 4 — Reference <a class="header-anchor" href="#part-4-—-reference" aria-label="Permalink to &quot;Part 4 — Reference&quot;">​</a></h2><h3 id="_4-1-chat-commands-mention-the-bot-in-the-team-space" tabindex="-1">4.1 Chat commands (mention the bot in the team space) <a class="header-anchor" href="#_4-1-chat-commands-mention-the-bot-in-the-team-space" aria-label="Permalink to &quot;4.1 Chat commands (mention the bot in the team space)&quot;">​</a></h3><p>Prefix with <code>#&lt;id&gt;</code> when the space has several standups. <strong>Open to everyone</strong>: <code>help</code>, <code>status</code>, <code>trends</code>, <code>blockers</code>, <code>blocker</code>, <code>poll</code>, <code>polls</code>, <code>export</code> — plus <code>setup</code> (there&#39;s nobody to gate it before the first standup exists). Everything else needs a standup admin.</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>setup [name]</code></td><td>Create a standup (creator becomes admin; duplicate names refused)</td></tr><tr><td><code>run now</code></td><td>Open today&#39;s run immediately and prompt everyone</td></tr><tr><td><code>archive</code></td><td>Retire the standup — prompts stop, history stays</td></tr><tr><td><code>add @user…</code> / <code>remove @user…</code></td><td>Manage the roster (add warns if the person can&#39;t be DMed yet)</td></tr><tr><td><code>mandatory @user…</code> / <code>optional @user…</code></td><td>Count toward the wrap-up, or not</td></tr><tr><td><code>vacation @user…</code> / <code>back @user…</code></td><td>Mark people away / back</td></tr><tr><td><code>admin @user…</code> / <code>unadmin @user…</code></td><td>Grant/revoke standup admin (never below one)</td></tr><tr><td><code>time HH:MM</code></td><td>Prompt time — participant-local</td></tr><tr><td><code>deadline HH:MM</code></td><td>Close time — standup timezone</td></tr><tr><td><code>remind &lt;minutes&gt;</code></td><td>Nudge before the deadline (0 disables, max 1440)</td></tr><tr><td><code>timezone &lt;IANA&gt;</code></td><td>Standup timezone</td></tr><tr><td><code>days mon,tue,…</code></td><td>Run days</td></tr><tr><td><code>questions</code> / <code>questions set Q1 | Q2 | …</code> / <code>questions reset</code></td><td>The form (1–10 questions, ≤200 chars)</td></tr><tr><td><code>mood on|off|anon</code> (also <code>anonymous</code>)</td><td>Mood dropdown; anon shows only the team average</td></tr><tr><td><code>escalate @user</code> / <code>escalate days N</code> / <code>escalate off</code></td><td>Stale-blocker escalation</td></tr><tr><td><code>digest on|off</code></td><td>Weekly digest</td></tr><tr><td><code>status</code></td><td>Config + today&#39;s progress (no <code>#id</code> → every standup in the space)</td></tr><tr><td><code>trends</code></td><td>Last 4 weeks: participation and mood</td></tr><tr><td><code>blockers</code> / <code>blocker &lt;id&gt; tag|update|resolve</code></td><td>Blocker list / collaboration</td></tr><tr><td><code>poll Q? | A | B</code> / <code>polls</code> / <code>poll &lt;id&gt; results</code> / <code>poll &lt;id&gt; close</code></td><td>Team polls (2–6 options)</td></tr><tr><td><code>export</code></td><td>How to download the CSV</td></tr></tbody></table><p>DM commands are in <a href="#32-dm-commands-message-the-bot-directly">Part 3</a>.</p><h3 id="_4-2-http-endpoints" tabindex="-1">4.2 HTTP endpoints <a class="header-anchor" href="#_4-2-http-endpoints" aria-label="Permalink to &quot;4.2 HTTP endpoints&quot;">​</a></h3><p>All token comparisons are constant-time; ✱ = covered by the rate limiter (60 requests/min/IP).</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Auth</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /healthz</code></td><td>none</td><td>Liveness (pings the DB)</td></tr><tr><td><code>GET /health/chat</code></td><td>none</td><td>Chat connection state without secrets: audience/key set, last verified or rejected event time</td></tr><tr><td><code>POST /chat/events</code></td><td>Google-signed JWT (verified against your audience)</td><td>Chat webhook — refuses events until the audience is configured</td></tr><tr><td><code>POST /tick</code> ✱</td><td>Bearer tick token (open until one exists)</td><td>External cron for scale-to-zero</td></tr><tr><td><code>GET /export?standupId=N&amp;days=D</code> ✱</td><td>Bearer export token (404 until one exists)</td><td>CSV, D clamped 1–365</td></tr><tr><td><code>GET /app[/…]</code></td><td>Session cookie, or an operator token entered on the sign-in page</td><td>The web app: sign-in, console shell, the standups home (stats strip + table), each standup&#39;s Overview, History, Insights and Settings, the cross-standup Blockers, Reports and Team views, workspace Settings (General, Google Chat, Sign-in &amp; SSO, MCP server, API &amp; tokens, Danger zone), the member console at <code>/app/me</code> (today&#39;s standup with a Chat deep link, my standups, recent answers, timezone and vacation), a phone layout with a bottom tab bar, and the guided setup at <code>/app/setup</code> (Cloud project → service account → Chat app with live verification → sign-in → first standup from a template, run immediately); the server-rendered dashboard is gone</td></tr><tr><td><code>POST /mcp</code> ✱</td><td>Bearer MCP token (503 while switched off)</td><td>Model Context Protocol endpoint for the team&#39;s own assistants; tokens and scopes under Settings › MCP server — <a href="./api.html#mcp-server">details</a></td></tr><tr><td><code>/api/v1/…</code></td><td>Session cookie, or Bearer operator token</td><td>JSON API for the web app: standups (incl. create from a template), spaces, runs, roster, blockers, team, me, settings, verification — <a href="./api.html">details</a></td></tr><tr><td><code>GET /auth/google</code>, <code>GET /auth/callback</code>, <code>POST /auth/logout</code> ✱</td><td>— (OAuth state nonce)</td><td>Google sign-in</td></tr><tr><td><code>GET /auth/saml</code>, <code>POST /auth/saml/acs</code>, <code>GET /auth/saml/metadata</code> ✱</td><td>— (signed assertions)</td><td>SAML sign-in + SP metadata</td></tr><tr><td><code>/scim/v2/ServiceProviderConfig</code>, <code>/scim/v2/Users[…]</code> ✱</td><td>Bearer SCIM token (404 until one exists)</td><td>SCIM 2.0: GET (list <code>startIndex</code>/<code>count</code> ≤200, <code>userName eq</code> filter, by id), POST, PUT, PATCH, DELETE; unsupported filters → 501</td></tr></tbody></table><h3 id="_4-3-settings" tabindex="-1">4.3 Settings <a class="header-anchor" href="#_4-3-settings" aria-label="Permalink to &quot;4.3 Settings&quot;">​</a></h3><p id="env-vars"><strong>Environment variables (bootstrap only)</strong></p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>8080</code></td><td>HTTP port</td></tr><tr><td><code>DB_PATH</code></td><td><code>./data/standup.db</code></td><td>SQLite file</td></tr><tr><td><code>DATABASE_URL</code></td><td>–</td><td>PostgreSQL instead of SQLite</td></tr><tr><td><code>DB_SSL</code> / <code>DB_SSL_CA</code></td><td>from URL</td><td>Postgres TLS mode / CA bundle</td></tr><tr><td><code>DASHBOARD_TOKEN</code></td><td>–</td><td>Operator token for the web app and the JSON API — break-glass once Google or SAML sign-in works</td></tr><tr><td><code>SECRET_KEY</code></td><td>required</td><td>Encrypts stored secrets; signs sessions and webhooks</td></tr><tr><td><code>ADAPTER</code></td><td><code>google</code></td><td><code>fake</code> for a credential-free local demo</td></tr><tr><td><code>TENANT_ID</code></td><td><code>default</code></td><td>Tenant scoping (multi-tenant installs)</td></tr></tbody></table><p><strong>Dashboard settings</strong> (stored in the DB, secrets encrypted, applied live; each value has its own box and saves on its own): Chat audience + service-account key · AI provider/key/model · default timezone · Calendar OOO · Workspace admin email · OAuth client · SAML IdP (entity ID, SSO URL, certificate, admin attribute + group) · token sign-in on/off (off only reachable once Google or SAML works; recover with <code>DELETE FROM settings WHERE key = &#39;tokenSignIn&#39;</code> + restart) · tick / export / SCIM tokens. Secrets are write-only — the UI shows <em>that</em> they&#39;re set, never the value. The settings UI refuses any change that would remove the last working sign-in method.</p><h3 id="webhooks-ref" tabindex="-1">4.4 Webhooks <a class="header-anchor" href="#webhooks-ref" aria-label="Permalink to &quot;4.4 Webhooks {#webhooks-ref}&quot;">​</a></h3><p>Per-standup URL (Standup › Settings › Integrations). JSON POST, 5 s timeout, failures only logged. Events: <code>{&quot;event&quot;:&quot;submission&quot;, standup, date, user, answers, mood, late, edited}</code> and <code>{&quot;event&quot;:&quot;wrap_up&quot;, standup, date, summary}</code>. Every delivery carries <code>X-AsyncUp-Signature: sha256=&lt;hex&gt;</code> — HMAC-SHA256 of the raw body with the standup&#39;s signing secret (shown in the standup&#39;s settings; derived from <code>SECRET_KEY</code>, so rotating that rotates it). Verify with a constant-time compare and reject mismatches.</p><h3 id="_4-5-who-can-do-what" tabindex="-1">4.5 Who can do what <a class="header-anchor" href="#_4-5-who-can-do-what" aria-label="Permalink to &quot;4.5 Who can do what&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>How you get it</th><th>What it grants</th></tr></thead><tbody><tr><td>Operator</td><td>Runs the server (<code>DASHBOARD_TOKEN</code>, env)</td><td>Everything, including app settings</td></tr><tr><td>Workspace admin</td><td>Google Workspace super/delegated admin (via Directory), or the SAML admin group</td><td>Full admin console for all standups</td></tr><tr><td>Standup admin</td><td>Ran <code>setup</code>, or granted <code>admin @user</code></td><td>Configure that standup from Chat</td></tr><tr><td>Participant</td><td><code>add @user</code></td><td>Submit, edit, skip, DM self-service, own page at <code>/app/me</code></td></tr><tr><td>Everyone in the space</td><td>—</td><td><code>status</code>, <code>trends</code>, <code>blockers</code>, polls, <code>help</code></td></tr></tbody></table>`,65)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
